const { contextBridge, ipcRenderer } = require("electron/main");  

const syncProfilePending = new Map()

function normalizeSyncProfileName(value) {
    const raw = String(value || '').trim()
    if (!raw) return ''
    return /\.zip$/i.test(raw) ? raw : raw + '.zip'
}

function completeSyncProfile(key, result) {
    const pending = syncProfilePending.get(key)
    if (!pending) return false
    syncProfilePending.delete(key)
    if (pending.timeout) clearTimeout(pending.timeout)
    for (const callback of pending.callbacks) {
        try { callback(result) } catch (error) {
            console.warn('[sync-profile] callback failed:', error?.message || error)
        }
    }
    return true
}

ipcRenderer.on("sync-profile-done", (_event, result) => {
    const key = normalizeSyncProfileName(result?.profileUniqueName)
    if (!key) return
    completeSyncProfile(key, result)
})

contextBridge.exposeInMainWorld('electron', {
    minimizeWindow: () => ipcRenderer.invoke('window-minimize'),
    maximizeWindow: () => ipcRenderer.invoke('window-maximize'),
    closeWindow: () => ipcRenderer.invoke('window-close'),
    openBrowser: (data) => ipcRenderer.invoke('open-browser', data),
    closeBrowser: (data) => ipcRenderer.invoke('close-browser', data),
    // Which profiles are actually running right now (array of profileUniqueName).
    // The renderer calls this on mount to restore play/stop buttons after a page
    // reload, since its in-memory button state is otherwise lost.
    getRunningBrowsers: () => ipcRenderer.invoke('get-running-browsers'),
    // Fires when a launched browser process exits (incl. the user closing the
    // window directly), so the renderer can flip the button back to "play".
    onBrowserClosed: (callback) => ipcRenderer.on('browser-closed', (event, payload) => callback(payload)),
    onDownloadProgress: (callback) => ipcRenderer.on('download-progress', (event, percent, name) => callback(percent, name)),
    syncProfile: (profile, cb) => {
        const key = normalizeSyncProfileName(profile?.profileUniqueName)
        const callback = typeof cb === 'function' ? cb : () => {}
        if (!key) {
            const result = { error: true, message: 'Invalid profile name', profileUniqueName: '' }
            callback(result)
            return Promise.resolve(result)
        }

        const active = syncProfilePending.get(key)
        if (active) {
            active.callbacks.push(callback)
            return active.promise
        }

        const pending = { callbacks: [callback], promise: null, timeout: null }
        syncProfilePending.set(key, pending)
        pending.timeout = setTimeout(() => {
            if (syncProfilePending.get(key) !== pending) return
            completeSyncProfile(key, {
                error: true,
                message: 'Profile sync timed out',
                profileUniqueName: key,
            })
        }, 15 * 60 * 1000)
        if (typeof pending.timeout?.unref === 'function') pending.timeout.unref()

        pending.promise = ipcRenderer.invoke('sync-profile', profile).catch((error) => {
            const result = {
                error: true,
                message: String(error?.message || error || 'Profile sync failed'),
                profileUniqueName: key,
            }
            completeSyncProfile(key, result)
            return result
        })
        return pending.promise
    },
    clearCacheProfile: (list) => ipcRenderer.invoke('clear-profile-cache', list),
    saveCatalogCache: (data) => ipcRenderer.invoke('catalog-cache-save', data || {}),
    loadCatalogCache: () => ipcRenderer.invoke('catalog-cache-load'),
    // Open the local KAIZEN diagnostics directory in Windows Explorer.
    openDiagnosticsFolder: () => ipcRenderer.invoke('diagnostics-open-folder'),
    exportExtensionSessions: () => ipcRenderer.invoke('extension-sessions-export'),
    // ── Remembered login ────────────────────────────────────────────────────
    // The password never travels as plain text on disk: the main process seals
    // it with safeStorage (OS-managed key). loadCredentials returns
    // { email, password }, where password is "" when nothing was stored or the
    // blob could not be opened on this machine.
    loadCredentials: () => ipcRenderer.invoke('creds-load'),
    saveCredentials: (data) => ipcRenderer.invoke('creds-save', data),
    clearCredentials: () => ipcRenderer.invoke('creds-clear'),
    // Renew an expired server session using remembered credentials. The server still validates the login normally.
    refreshSession: (data) => ipcRenderer.invoke('session-refresh', data || {}),
    loadTwofaToken: () => ipcRenderer.invoke('twofa-load'),
    saveTwofaToken: (token) => ipcRenderer.invoke('twofa-save', token || ''),
    clearTwofaToken: () => ipcRenderer.invoke('twofa-clear'),
    // ── Auto-update bridge ──────────────────────────────────────────────────
    // Lifecycle state: { state: "idle"|"checking"|"available"|"none"|"downloaded"|"error", version?, message? }
    onUpdateStatus: (callback) => ipcRenderer.on('update-status', (event, payload) => callback(payload)),
    // Live download progress: { percent, transferred, total, bytesPerSecond }
    onUpdateProgress: (callback) => ipcRenderer.on('update-progress', (event, payload) => callback(payload)),
    // Pull the latest cached state on mount (covers events fired pre-load).
    // Version of the running build, e.g. "1.4.3" — shown in the topbar.
    getAppVersion: () => ipcRenderer.invoke('app-get-version'),
    getUpdateState: () => ipcRenderer.invoke('update-get-state'),
    // Force a manual check (e.g. a "Check for updates" button).
    checkForUpdates: () => ipcRenderer.invoke('update-check'),
    // Quit, install the downloaded update, and relaunch.
    installUpdate: () => ipcRenderer.invoke('update-install'),
})

function installExtensionSessionsButton() {
    try {
        if (document.getElementById('kaizen-extension-sessions-button')) return
        const button = document.createElement('button')
        button.id = 'kaizen-extension-sessions-button'
        button.type = 'button'
        button.textContent = '⬇ Sesiones LAB'
        button.title = 'Exportar en texto plano el estado interno de las extensiones KAIZZEN activas (LAB)'
        button.setAttribute('aria-label', 'Exportar sesiones de prueba en texto plano de extensiones KAIZZEN')
        Object.assign(button.style, {
            position: 'fixed',
            right: '24px',
            bottom: '72px',
            zIndex: '2147483647',
            padding: '10px 14px',
            border: '1px solid rgba(255,255,255,.16)',
            borderRadius: '10px',
            background: '#111827',
            color: '#ffffff',
            fontFamily: 'system-ui, -apple-system, Segoe UI, sans-serif',
            fontSize: '13px',
            fontWeight: '600',
            lineHeight: '18px',
            cursor: 'pointer',
            boxShadow: '0 8px 24px rgba(0,0,0,.22)',
            userSelect: 'none'
        })
        button.addEventListener('mouseenter', () => { button.style.transform = 'translateY(-1px)' })
        button.addEventListener('mouseleave', () => { button.style.transform = '' })
        button.addEventListener('click', async () => {
            if (button.disabled) return
            const normalText = '⬇ Sesiones LAB'
            button.disabled = true
            button.textContent = 'Exportando…'
            try {
                const result = await ipcRenderer.invoke('extension-sessions-export')
                if (result?.ok) {
                    button.textContent = result.extensions > 0 ? `✓ ${result.extensions} sesión${result.extensions === 1 ? '' : 'es'}` : 'Sin sesiones activas'
                } else {
                    button.textContent = 'No se pudo exportar'
                    button.title = result?.reason || 'No se pudo exportar'
                }
            } catch (error) {
                console.warn('[extension-sessions-button] export failed:', error?.message || error)
                button.textContent = 'No se pudo exportar'
            } finally {
                setTimeout(() => {
                    button.disabled = false
                    button.textContent = normalText
                }, 2200)
            }
        })
        document.body.appendChild(button)
    } catch (error) {
        console.warn('[extension-sessions-button] unavailable:', error?.message || error)
    }
}

function installDiagnosticsButton() {
    try {
        if (document.getElementById('kaizen-diagnostics-folder-button')) return
        const button = document.createElement('button')
        button.id = 'kaizen-diagnostics-folder-button'
        button.type = 'button'
        button.textContent = '📁 Diagnóstico'
        button.title = 'Abrir la carpeta donde KAIZEN guarda las capturas de diagnóstico'
        button.setAttribute('aria-label', 'Abrir carpeta de diagnóstico')
        Object.assign(button.style, {
            position: 'fixed',
            right: '24px',
            bottom: '24px',
            zIndex: '2147483647',
            padding: '10px 14px',
            border: '1px solid rgba(255,255,255,.16)',
            borderRadius: '10px',
            background: '#111827',
            color: '#ffffff',
            fontFamily: 'system-ui, -apple-system, Segoe UI, sans-serif',
            fontSize: '13px',
            fontWeight: '600',
            lineHeight: '18px',
            cursor: 'pointer',
            boxShadow: '0 8px 24px rgba(0,0,0,.22)',
            userSelect: 'none'
        })
        button.addEventListener('mouseenter', () => { button.style.transform = 'translateY(-1px)' })
        button.addEventListener('mouseleave', () => { button.style.transform = '' })
        button.addEventListener('click', async () => {
            if (button.disabled) return
            const normalText = '📁 Diagnóstico'
            button.disabled = true
            button.textContent = 'Abriendo…'
            try {
                const result = await ipcRenderer.invoke('diagnostics-open-folder')
                if (!result?.ok) {
                    console.warn('[diagnostics-button] could not open folder:', result?.error || 'unknown')
                    button.textContent = 'No se pudo abrir'
                    button.title = result?.error || 'No se pudo abrir la carpeta de diagnóstico'
                    setTimeout(() => { button.textContent = normalText }, 1800)
                }
            } catch (error) {
                console.warn('[diagnostics-button] could not open folder:', error?.message || error)
                button.textContent = 'No se pudo abrir'
                setTimeout(() => { button.textContent = normalText }, 1800)
            } finally {
                setTimeout(() => {
                    button.disabled = false
                    if (button.textContent === 'Abriendo…') button.textContent = normalText
                }, 250)
            }
        })
        document.body.appendChild(button)
    } catch (error) {
        console.warn('[diagnostics-button] unavailable:', error?.message || error)
    }
}


function guestRouteIsLogin() {
    const hash = String(window.location.hash || '').toLowerCase()
    return !hash || hash === '#' || hash === '#/' || hash.startsWith('#/login')
}

function guestProfileLabel(profile) {
    return String(profile?.profileName || profile?.name || profile?.profileUniqueName || 'Perfil sin nombre')
}

function closeGuestProfilesPanel() {
    const panel = document.getElementById('kaizen-guest-profiles-panel')
    if (panel) panel.remove()
}

async function openGuestProfilesPanel() {
    closeGuestProfilesPanel()

    const overlay = document.createElement('div')
    overlay.id = 'kaizen-guest-profiles-panel'
    Object.assign(overlay.style, {
        position: 'fixed',
        inset: '0',
        zIndex: '2147483646',
        background: 'rgba(3, 7, 18, .94)',
        backdropFilter: 'blur(14px)',
        display: 'flex',
        alignItems: 'center',
        justifyContent: 'center',
        padding: '24px',
        fontFamily: 'system-ui, -apple-system, Segoe UI, sans-serif',
        color: '#fff'
    })

    const box = document.createElement('div')
    Object.assign(box.style, {
        width: 'min(980px, 96vw)',
        height: 'min(760px, 90vh)',
        border: '1px solid rgba(255,255,255,.14)',
        borderRadius: '18px',
        background: '#0b1220',
        boxShadow: '0 30px 90px rgba(0,0,0,.55)',
        display: 'flex',
        flexDirection: 'column',
        overflow: 'hidden'
    })

    const header = document.createElement('div')
    Object.assign(header.style, {
        padding: '18px 20px',
        borderBottom: '1px solid rgba(255,255,255,.10)',
        display: 'flex',
        alignItems: 'center',
        gap: '12px'
    })

    const titleWrap = document.createElement('div')
    titleWrap.style.flex = '1'
    const title = document.createElement('div')
    title.textContent = '👤 Modo invitado'
    Object.assign(title.style, { fontSize: '18px', fontWeight: '750' })
    const subtitle = document.createElement('div')
    subtitle.textContent = 'Perfiles disponibles en el catálogo local de esta PC'
    Object.assign(subtitle.style, { marginTop: '4px', fontSize: '12px', color: '#94a3b8' })
    titleWrap.append(title, subtitle)

    const close = document.createElement('button')
    close.type = 'button'
    close.textContent = '✕'
    close.title = 'Cerrar modo invitado'
    Object.assign(close.style, {
        width: '38px',
        height: '38px',
        borderRadius: '10px',
        border: '1px solid rgba(255,255,255,.14)',
        background: '#111827',
        color: '#fff',
        cursor: 'pointer',
        fontSize: '16px'
    })
    close.addEventListener('click', closeGuestProfilesPanel)
    header.append(titleWrap, close)

    const toolbar = document.createElement('div')
    Object.assign(toolbar.style, {
        padding: '14px 20px',
        display: 'flex',
        gap: '12px',
        alignItems: 'center',
        borderBottom: '1px solid rgba(255,255,255,.08)'
    })

    const search = document.createElement('input')
    search.type = 'search'
    search.placeholder = 'Buscar perfil…'
    Object.assign(search.style, {
        flex: '1',
        minWidth: '0',
        padding: '10px 12px',
        borderRadius: '10px',
        border: '1px solid rgba(255,255,255,.14)',
        background: '#111827',
        color: '#fff',
        outline: 'none',
        fontSize: '13px'
    })

    const count = document.createElement('div')
    Object.assign(count.style, { fontSize: '12px', color: '#94a3b8', whiteSpace: 'nowrap' })
    toolbar.append(search, count)

    const body = document.createElement('div')
    Object.assign(body.style, {
        flex: '1',
        overflow: 'auto',
        padding: '14px 20px 20px'
    })

    const status = document.createElement('div')
    status.textContent = 'Cargando perfiles locales…'
    Object.assign(status.style, {
        padding: '28px 10px',
        textAlign: 'center',
        color: '#94a3b8',
        fontSize: '13px'
    })
    body.appendChild(status)

    box.append(header, toolbar, body)
    overlay.appendChild(box)
    document.body.appendChild(overlay)

    overlay.addEventListener('click', (event) => {
        if (event.target === overlay) closeGuestProfilesPanel()
    })

    let profiles = []
    try {
        const result = await ipcRenderer.invoke('catalog-cache-load')
        profiles = result?.ok && Array.isArray(result.profiles) ? result.profiles : []
    } catch (error) {
        console.warn('[guest-mode] catalog load failed:', error?.message || error)
    }

    const render = () => {
        const query = String(search.value || '').trim().toLowerCase()
        const filtered = profiles.filter((profile) => {
            if (!query) return true
            const haystack = [
                guestProfileLabel(profile),
                profile?.profileUniqueName,
                profile?.group,
                profile?.browser,
                profile?.profileType
            ].map(value => String(value || '').toLowerCase()).join(' ')
            return haystack.includes(query)
        })

        count.textContent = query
            ? `${filtered.length} de ${profiles.length}`
            : `${profiles.length} perfil${profiles.length === 1 ? '' : 'es'}`

        body.replaceChildren()

        if (!profiles.length) {
            const empty = document.createElement('div')
            empty.textContent = 'No hay perfiles guardados todavía en el catálogo local.'
            Object.assign(empty.style, {
                padding: '32px 10px',
                textAlign: 'center',
                color: '#94a3b8',
                fontSize: '13px'
            })
            body.appendChild(empty)
            return
        }

        if (!filtered.length) {
            const empty = document.createElement('div')
            empty.textContent = 'No se encontraron perfiles con esa búsqueda.'
            Object.assign(empty.style, {
                padding: '32px 10px',
                textAlign: 'center',
                color: '#94a3b8',
                fontSize: '13px'
            })
            body.appendChild(empty)
            return
        }

        const grid = document.createElement('div')
        Object.assign(grid.style, {
            display: 'grid',
            gridTemplateColumns: 'repeat(auto-fill, minmax(260px, 1fr))',
            gap: '10px'
        })

        for (const profile of filtered) {
            const card = document.createElement('div')
            Object.assign(card.style, {
                border: '1px solid rgba(255,255,255,.10)',
                borderRadius: '14px',
                background: '#111827',
                padding: '14px',
                display: 'flex',
                flexDirection: 'column',
                gap: '10px'
            })

            const name = document.createElement('div')
            name.textContent = guestProfileLabel(profile)
            Object.assign(name.style, {
                fontSize: '14px',
                fontWeight: '700',
                overflow: 'hidden',
                textOverflow: 'ellipsis',
                whiteSpace: 'nowrap'
            })

            const meta = document.createElement('div')
            const metaParts = [
                profile?.group ? `Grupo: ${profile.group}` : '',
                profile?.browser ? `Navegador: ${profile.browser}` : '',
                profile?.profileType ? `Tipo: ${profile.profileType}` : ''
            ].filter(Boolean)
            meta.textContent = metaParts.join(' · ') || String(profile?.profileUniqueName || '')
            Object.assign(meta.style, {
                minHeight: '32px',
                fontSize: '11px',
                lineHeight: '16px',
                color: '#94a3b8',
                wordBreak: 'break-word'
            })

            const open = document.createElement('button')
            open.type = 'button'
            open.textContent = 'Abrir'
            Object.assign(open.style, {
                width: '100%',
                padding: '9px 12px',
                border: '1px solid rgba(96,165,250,.38)',
                borderRadius: '10px',
                background: '#172554',
                color: '#dbeafe',
                fontWeight: '700',
                cursor: 'pointer',
                fontSize: '12px'
            })

            open.addEventListener('click', async () => {
                if (open.disabled) return
                const normalText = 'Abrir'
                open.disabled = true
                open.textContent = 'Abriendo…'
                try {
                    const localProfile = { ...profile }
                    delete localProfile.token
                    const result = await ipcRenderer.invoke('open-browser', localProfile)
                    if (result?.error) throw new Error(result.message || 'No se pudo abrir el perfil')
                    open.textContent = '✓ Abierto'
                } catch (error) {
                    console.warn('[guest-mode] profile open failed:', error?.message || error)
                    open.textContent = 'No se pudo abrir'
                    open.title = String(error?.message || error || 'No se pudo abrir el perfil')
                } finally {
                    setTimeout(() => {
                        open.disabled = false
                        open.textContent = normalText
                    }, 1800)
                }
            })

            card.append(name, meta, open)
            grid.appendChild(card)
        }

        body.appendChild(grid)
    }

    search.addEventListener('input', render)
    render()
    setTimeout(() => search.focus(), 0)
}

function installGuestProfilesButton() {
    try {
        if (document.getElementById('kaizen-guest-profiles-button')) return
        const button = document.createElement('button')
        button.id = 'kaizen-guest-profiles-button'
        button.type = 'button'
        button.textContent = '👤 Invitado'
        button.title = 'Abrir todos los perfiles guardados en el catálogo local'
        button.setAttribute('aria-label', 'Entrar como invitado usando perfiles locales')
        Object.assign(button.style, {
            position: 'fixed',
            left: '24px',
            bottom: '24px',
            zIndex: '2147483647',
            padding: '11px 16px',
            border: '1px solid rgba(96,165,250,.38)',
            borderRadius: '10px',
            background: '#172554',
            color: '#dbeafe',
            fontFamily: 'system-ui, -apple-system, Segoe UI, sans-serif',
            fontSize: '13px',
            fontWeight: '700',
            lineHeight: '18px',
            cursor: 'pointer',
            boxShadow: '0 8px 24px rgba(0,0,0,.28)',
            userSelect: 'none'
        })
        button.addEventListener('mouseenter', () => { button.style.transform = 'translateY(-1px)' })
        button.addEventListener('mouseleave', () => { button.style.transform = '' })
        button.addEventListener('click', openGuestProfilesPanel)
        document.body.appendChild(button)

        const syncVisibility = () => {
            button.style.display = guestRouteIsLogin() ? 'block' : 'none'
            if (!guestRouteIsLogin()) closeGuestProfilesPanel()
        }
        window.addEventListener('hashchange', syncVisibility)
        syncVisibility()
    } catch (error) {
        console.warn('[guest-mode] button unavailable:', error?.message || error)
    }
}

if (document.readyState === 'loading') {
    window.addEventListener('DOMContentLoaded', () => {
        installDiagnosticsButton()
        installExtensionSessionsButton()
        installGuestProfilesButton()
    }, { once: true })
} else {
    installDiagnosticsButton()
    installExtensionSessionsButton()
    installGuestProfilesButton()
}

console.log('...PRELOADED...');